input.command:
cd /home/vercel-sandbox/reflex-starter-template; sed -n 38,48p Dockerfile
git rm -q railway.toml
cat > .railway/railway.ts <<'EOF'
import { defineRailway, github, project, service } from "railway/iac";
// This repository manages only its own resources in the environment.
// See https://docs.railway.com/infrastructure-as-code#multi-repo-projects
export const partial = "web";
export default defineRailway(() => {
  const web = service("web", {
    source: github("elviskahoro/reflex-starter-template", { branch: "main", checkSuites: false }),
    // Uppercase DOCKERFILE is required; lowercase is not persisted.
    build: { builder: "DOCKERFILE", dockerfilePath: "Dockerfile", watchPatterns: ["Dockerfile", "pyproject.toml", "uv.lock", "web/**", "Caddyfile", "entrypoint.sh"] },
    deploy: { restartPolicyType: "ON_FAILURE", restartPolicyMaxRetries: 5, drainingSeconds: 30 },
    healthcheck: "/ping",
    healthcheckTimeout: 10,
  });

  return project("reflex-starter-template", {
    variables: { managed: false },
    resources: [web],
  });
});
EOF
cat > package.json <<'EOF'
{
  "name": "reflex-starter-template-railway-iac",
  "private": true,
  "type": "module",
  "description": "Only exists so `railway config plan/apply` can resolve the railway/iac SDK for .railway/railway.ts. Not part of the Python app.",
  "devDependencies": {
    "railway": "^3.17.0"
  }
}
EOF
npm install --package-lock-only 2>&1 | tail -2
printf '\nnode_modules/\n' >> .gitignore
printf '\n.railway/\npackage.json\npackage-lock.json\n' >> .dockerignore
python3 - <<'EOF'
import re
r=open('README.md').read()
r=r.replace("# Railway build/deploy config","# (removed; see .railway/railway.ts)")
r=r.replace("defaults to `8080` per `railway.toml`","defaults to `8080`")
r=r.replace("`railway.toml` already configures: Dockerfile builder, `/ping` healthcheck, 30s draining, restart-on-failure (max 5), and `PORT=8080`.","`.railway/railway.ts` (Railway IaC) configures: Dockerfile builder, `/ping` healthcheck, 30s draining, and restart-on-failure (max 5). Run `npm ci` then `railway config plan` / `railway config apply`.")
r=r.replace("Already set in `railway.toml` (`[env]` block):","Set in the `Dockerfile` (`PORT` defaults to `8080`):")
r=r.replace("Do **not** put secrets in `railway.toml` — it is committed to git.","Do **not** put secrets in `.railway/railway.ts` — it is committed to git.")
open('README.md','w').write(r)
d=open('DEPLOYMENT.md').read()
d=d.replace("- **railway.toml**: Configures Railway-specific settings","- **.railway/railway.ts**: Railway infrastructure-as-code (replaces deprecated railway.toml)")
open('DEPLOYMENT.md','w').write(d)
EOF
sed -n 30,36p README.md; git status --short

